import {massBoundaryDiagram} from './model-diagrams.js?v=20261023-physicscomplete01';
import {stackedReadings} from './model-geometry.js?v=20261023-physicscomplete01';
import {renderDiagram,renderModel,enable3D} from './visual.js?v=20261023-physicscomplete01';
import {statistics,repeatSets} from './quant-models.js?v=20261023-physicscomplete01';
const text=(x,y,t,size=13)=>`<text x="${x}" y="${y}" fill="#d4dfe7" text-anchor="middle" font-family="sans-serif" font-size="${size}">${t}</text>`;
export function showLedger(t=null,reveal=false){renderDiagram('Follow the weighed boundary',t?.name||'Atoms rearrange; mass is conserved',massBoundaryDiagram(t,reveal),'BOOKKEEPING MODEL · NOT APPARATUS');}
export function showFormula(counts={H:2,O:1},formula='H₂O'){const atoms=[];for(const[el,n]of Object.entries(counts))for(let i=0;i<n;i++){const j=atoms.length;atoms.push([el,(j%5-2)*.75,(Math.floor(j/5)-.7)*.75,0]);}const diagram='<div class="diagram-card"><span class="eyebrow">YOUR ATOM COUNTS</span>'+Object.entries(counts).map(([e,n])=>'<p>'+e+': '+n+'</p>').join('')+'<p>Separate inventory symbols, not a structural formula.</p></div>';enable3D();renderModel({name:'Your atom inventory',formula,kicker:'SCHEMATIC FORMULA COUNT MODEL · NOT MOLECULAR GEOMETRY',aria:'Atom inventory for '+formula+': '+Object.entries(counts).map(([e,n])=>n+' '+e).join(', ')+'. No bonds or geometry are represented.',atoms,bonds:[],zoom:12,atomSize:.23,diagram});}
export function showPlot(values=repeatSets[0]){const s=statistics(values),step=s.range<=.1?.02:.1,lo=(Math.floor(Math.min(...values)/step+1e-8)-1)*step,hi=(Math.ceil(Math.max(...values)/step-1e-8)+1)*step;let art='<path d="M35 190H405" stroke="#b7c8d6" stroke-width="2"/>';const ticks=Math.round((hi-lo)/step);for(let i=0;i<=ticks;i++){const v=lo+step*i,x=35+i/ticks*370;art+=`<path d="M${x} 183V197" stroke="#b7c8d6"/>`+text(x,220,v.toFixed(2),11);}const mx=35+(s.mean-lo)/(hi-lo)*370;art+=`<path d="M${mx} 65V190" stroke="#f0b4a6" stroke-dasharray="4 4"/>`;stackedReadings(values).forEach(({value:v,level})=>{const x=35+(v-lo)/(hi-lo)*370;art+=`<circle cx="${x}" cy="${135-level*22}" r="7" fill="#d4dfe7"/>`+(level===0?text(x,165,v.toFixed(2),12):'');});art+=text(220,40,'Repeat measurements / g',16)+text(220,255,'Dashed: mean · axis rescales between sets',11);renderDiagram('Readings form a distribution',values.map(v=>v.toFixed(2)).join(' · ')+' g',`<svg class="lab-svg" viewBox="0 0 440 285" role="img" aria-label="Readings ${values.join(', ')} grams on a rescaled axis; dashed line marks the mean.">${art}</svg>`,'FICTIONAL REPEAT DATA · LABELLED AXIS');}
export function showQuant(kind){if(kind==='formula')showFormula();else if(kind==='plot')showPlot();else showLedger();}
